let lang=localStorage.getItem("yn-lang")||"ru",active="health";
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],tr=k=>dict[lang][k]??k,fmt=n=>new Intl.NumberFormat(lang==="ru"?"ru-RU":"en-US",{maximumFractionDigits:2}).format(n);
const names=["health","finance","marketing","market","risk","operations","adapt","plan"];
const startedTools=new Set();
function track(eventName){if(window.YNAnalytics)window.YNAnalytics.track(eventName,active)}
function trackToolStarted(){if(!startedTools.has(active)){startedTools.add(active);track("tool_started")}}
function translate(){document.documentElement.lang=lang;$$("[data-en]").forEach(e=>e.innerHTML=e.dataset[lang]||e.dataset.en);render(active);savedStatus()}
function setLang(){lang=lang==="en"?"ru":"en";localStorage.setItem("yn-lang",lang);translate()}
function head(n,title,desc){return '<div class="panel"><small>'+n+' / YOUNOVAL TOOLKIT</small><h3>'+title+'</h3><p>'+desc+'</p>'}
function field(id,label,placeholder="0"){return '<div class="field"><label for="'+id+'">'+label+'</label><input id="'+id+'" type="number" min="0" step="any" placeholder="'+placeholder+'"></div>'}
function selectField(id,label,options){return '<div class="field"><label for="'+id+'">'+label+'</label><select id="'+id+'">'+options.map((o,i)=>'<option value="'+i+'">'+o+'</option>').join("")+'</select></div>'}
function checklist(items,prefix){return '<div class="questions">'+items.map((q,i)=>'<div class="question"><label>'+String(i+1).padStart(2,"0")+'　'+q+'</label><select id="'+prefix+i+'">'+tr("opts").map((o,j)=>'<option value="'+j+'">'+o+'</option>').join("")+'</select></div>').join("")+'</div>'}
function render(which){active=names.includes(which)?which:"health";$$("[data-tab]").forEach(b=>b.classList.toggle("active",b.dataset.tab===active));let s="";
if(active==="health"||active==="operations"||active==="adapt"){
const cfg=active==="health"?["01",tr("health"),tr("intro"),tr("dims"),"h",tr("calculate")]:active==="operations"?["06",tr("operations"),tr("opsIntro"),tr("opsQs"),"o",tr("calculate")]:["07",tr("adapt"),tr("adaptIntro"),tr("adaptQs"),"a",tr("calculate")];
s=head(cfg[0],cfg[1],cfg[2])+checklist(cfg[3],cfg[4])+'<button class="calc" id="doChecklist">'+cfg[5]+'</button><div class="result" id="result"></div></div>';
}
if(active==="finance")s=head("02",tr("finance"),tr("financeIntro"))+'<div class="fields">'+field("cash",tr("cash"))+field("inflows",tr("inflows"))+field("outflows",tr("outflows"))+field("fixed",tr("fixed"))+field("price",tr("price"))+field("variable",tr("variable"))+'</div><button class="calc" id="doFinance">'+tr("calcFinance")+'</button><div class="result" id="result"></div></div>';
if(active==="marketing")s=head("03",tr("marketing"),tr("marketingIntro"))+'<div class="fields">'+field("spend",tr("spend"))+field("customers",tr("customers"))+field("visitors",tr("visitors"))+field("orders",tr("orders"))+field("revenue",tr("revenue"))+'</div><button class="calc" id="doMarketing">'+tr("calcMarketing")+'</button><div class="result" id="result"></div></div>';
if(active==="market")s=head("04",tr("market"),tr("marketIntro"))+checklist(tr("marketQs"),"m")+'<div class="field market-note"><label for="marketEvidence">'+(lang==="ru"?"Какое доказательство оказалось самым убедительным?":"Which piece of evidence was most convincing?")+'</label><input id="marketEvidence" type="text" maxlength="180" placeholder="'+(lang==="ru"?"Краткая заметка (необязательно)":"Short note (optional)")+'"></div><button class="calc" id="doMarket">'+tr("calculate")+'</button><div class="result" id="result"></div></div>';
if(active==="risk")s=head("05",tr("risk"),tr("riskIntro"))+'<div class="risk-list">'+tr("riskQs").map((q,i)=>'<div class="risk-item"><h4>'+String(i+1).padStart(2,"0")+'　'+q+'</h4><div class="fields">'+selectField("rp"+i,tr("prob"),["1","2","3","4","5"])+selectField("ri"+i,tr("impact"),["1","2","3","4","5"])+'</div><div class="field"><label for="rm'+i+'">'+tr("mitigation")+'</label><input id="rm'+i+'" maxlength="180" type="text" placeholder="'+(lang==="ru"?"Краткий план (необязательно)":"Short response (optional)")+'"></div></div>').join("")+'</div><button class="calc" id="doRisk">'+tr("calculate")+'</button><div class="result" id="result"></div></div>';
if(active==="plan")s=head("08",tr("plan"),tr("planIntro"))+'<div class="plan-source" id="planSource"></div><div class="field plan-goal"><label for="planFocus">'+tr("focus")+'</label><input id="planFocus" type="text" maxlength="180" placeholder="'+(lang==="ru"?"Например: увеличить число повторных покупок с 20 до 30 в месяц":"e.g. increase repeat purchases from 20 to 30 per month")+'"></div><button class="calc" id="doPlan">'+tr("planBtn")+'</button><div class="result" id="result"></div></div>';
$("#panel").innerHTML=s;wire()}
function input(id){const e=$("#"+id);return e&&e.value.trim()!==""?Number(e.value):NaN}
function save(data){try{const all=JSON.parse(localStorage.getItem("yn-results")||"{}");all[active]={...data,date:new Date().toISOString()};localStorage.setItem("yn-results",JSON.stringify(all));savedStatus()}catch(e){toast(lang==="ru"?"Не удалось сохранить результат в этом браузере.":"Could not save results in this browser.")}}
function savedStatus(){const all=JSON.parse(localStorage.getItem("yn-results")||"{}");$("#saved").textContent=Object.keys(all).length?tr("saved")+Object.keys(all).length:(lang==="en"?"Your results will appear here after you complete a tool.":"Здесь появятся результаты после прохождения инструмента.");$("#clear").textContent=lang==="en"?"Clear saved results":"Очистить результаты"}
function escapeHTML(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function result(title,metrics,analysis,actions,data,percent){
const box=$("#result");
const list=items=>'<ul>'+items.map(x=>'<li>'+escapeHTML(x)+'</li>').join("")+'</ul>';
box.innerHTML='<div class="result-title"><h4>'+escapeHTML(title)+'</h4></div><div class="metrics">'+metrics.map(m=>'<div><strong>'+escapeHTML(m[0])+'</strong><small>'+escapeHTML(m[1])+'</small></div>').join("")+'</div>'+(percent===undefined?"":'<div class="bar"><span style="width:'+Math.max(0,Math.min(100,percent))+'%"></span></div>')+'<section class="result-section"><h5>'+(lang==="ru"?"Подробный анализ":"Detailed analysis")+'</h5>'+list(analysis)+'</section><section class="result-section solution"><h5>'+(lang==="ru"?"Что делать: пошаговое решение":"What to do: step-by-step solution")+'</h5>'+list(actions)+'</section><p class="result-disclaimer">'+tr("notPrediction")+'</p>';
box.classList.add("show");save(data);trackToolStarted();track("tool_completed")
}
function toast(msg){const el=$("#toast");el.textContent=msg;el.classList.add("show");setTimeout(()=>el.classList.remove("show"),2200)}
